// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// RequestTokenEmail Send a verification, recovery, sign-in or code email
	// (POST /auth/email/request)
	RequestTokenEmail(ctx context.Context, request RequestTokenEmailRequestObject) (RequestTokenEmailResponseObject, error)
	// ConfirmEmailVerification Confirm an email address with a verification token
	// (POST /auth/email/verify)
	ConfirmEmailVerification(ctx context.Context, request ConfirmEmailVerificationRequestObject) (ConfirmEmailVerificationResponseObject, error)
	// Login Exchange credentials for a session
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ConsumeMagicLink Sign in with a magic link token
	// (POST /auth/magic/consume)
	ConsumeMagicLink(ctx context.Context, request ConsumeMagicLinkRequestObject) (ConsumeMagicLinkResponseObject, error)
	// ConsumeOTP Sign in with a one-time code
	// (POST /auth/otp/consume)
	ConsumeOTP(ctx context.Context, request ConsumeOTPRequestObject) (ConsumeOTPResponseObject, error)
	// ConfirmPasswordReset Set a new password with a recovery token
	// (POST /auth/password/reset)
	ConfirmPasswordReset(ctx context.Context, request ConfirmPasswordResetRequestObject) (ConfirmPasswordResetResponseObject, error)
	// Refresh Rotate the session using a refresh token
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Register Register a candidate or an organisation
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ListDisciplines List the professions the product serves
	// (GET /catalog/disciplines)
	ListDisciplines(ctx context.Context, request ListDisciplinesRequestObject) (ListDisciplinesResponseObject, error)
	// ListInterviewShapes List interview shapes with their runnable lengths
	// (GET /catalog/interview-shapes)
	ListInterviewShapes(ctx context.Context, request ListInterviewShapesRequestObject) (ListInterviewShapesResponseObject, error)
	// ListPersonas List interviewer personas
	// (GET /catalog/personas)
	ListPersonas(ctx context.Context, request ListPersonasRequestObject) (ListPersonasResponseObject, error)
	// ListRoles List catalogued roles with their valid combinations
	// (GET /catalog/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// GetLiveness Report whether the process is running
	// (GET /healthz)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// CreateInterview Create a practice interview from a catalogue selection
	// (POST /interviews)
	CreateInterview(ctx context.Context, request CreateInterviewRequestObject) (CreateInterviewResponseObject, error)
	// GetPracticeConsent The current practice recording consent text, versioned
	// (GET /interviews/practice-consent)
	GetPracticeConsent(ctx context.Context, request GetPracticeConsentRequestObject) (GetPracticeConsentResponseObject, error)
	// GetInterview One practice session, as its owner sees it
	// (GET /interviews/{sessionId})
	GetInterview(ctx context.Context, request GetInterviewRequestObject) (GetInterviewResponseObject, error)
	// CompleteInterview Seal the transcript and hand the session to evaluation
	// (POST /interviews/{sessionId}/complete)
	CompleteInterview(ctx context.Context, request CompleteInterviewRequestObject) (CompleteInterviewResponseObject, error)
	// ReplayControlEvents Replay the durable timeline after a cursor
	// (GET /interviews/{sessionId}/events)
	ReplayControlEvents(ctx context.Context, request ReplayControlEventsRequestObject) (ReplayControlEventsResponseObject, error)
	// IngestControlEvents Send a batch of control events for the current epoch
	// (POST /interviews/{sessionId}/events)
	IngestControlEvents(ctx context.Context, request IngestControlEventsRequestObject) (IngestControlEventsResponseObject, error)
	// GetResults The evaluation result, sufficiency and coverage included
	// (GET /interviews/{sessionId}/results)
	GetResults(ctx context.Context, request GetResultsRequestObject) (GetResultsResponseObject, error)
	// StartInterview Start a ready session and receive the room grant
	// (POST /interviews/{sessionId}/start)
	StartInterview(ctx context.Context, request StartInterviewRequestObject) (StartInterviewResponseObject, error)
	// GetTranscript The assembled transcript, provenance included
	// (GET /interviews/{sessionId}/transcript)
	GetTranscript(ctx context.Context, request GetTranscriptRequestObject) (GetTranscriptResponseObject, error)
	// GetCurrentUser Describe the authenticated user and their active tenant
	// (GET /me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// SetActiveTenant Choose which workspace this session acts under
	// (PUT /me/active-tenant)
	SetActiveTenant(ctx context.Context, request SetActiveTenantRequestObject) (SetActiveTenantResponseObject, error)
	// ListDocuments List the candidate's own documents, every version and state
	// (GET /me/documents)
	ListDocuments(ctx context.Context, request ListDocumentsRequestObject) (ListDocumentsResponseObject, error)
	// StartDocumentUpload Start a CV upload
	// (POST /me/documents)
	StartDocumentUpload(ctx context.Context, request StartDocumentUploadRequestObject) (StartDocumentUploadResponseObject, error)
	// DeleteDocument Delete a stored document
	// (DELETE /me/documents/{documentId})
	DeleteDocument(ctx context.Context, request DeleteDocumentRequestObject) (DeleteDocumentResponseObject, error)
	// AbortDocumentUpload Abandon a stalled upload
	// (POST /me/documents/{documentId}/abort)
	AbortDocumentUpload(ctx context.Context, request AbortDocumentUploadRequestObject) (AbortDocumentUploadResponseObject, error)
	// CompleteDocumentUpload Finalise an upload
	// (POST /me/documents/{documentId}/complete)
	CompleteDocumentUpload(ctx context.Context, request CompleteDocumentUploadRequestObject) (CompleteDocumentUploadResponseObject, error)
	// ListDocumentFacts List what extraction read from one document
	// (GET /me/documents/{documentId}/facts)
	ListDocumentFacts(ctx context.Context, request ListDocumentFactsRequestObject) (ListDocumentFactsResponseObject, error)
	// ReviewFact Confirm, correct or reject one extracted fact
	// (POST /me/facts/{factId}/review)
	ReviewFact(ctx context.Context, request ReviewFactRequestObject) (ReviewFactResponseObject, error)
	// ListMemberships List the workspaces this person belongs to
	// (GET /me/memberships)
	ListMemberships(ctx context.Context, request ListMembershipsRequestObject) (ListMembershipsResponseObject, error)
	// GetProfile Read the candidate's own profile
	// (GET /me/profile)
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// SaveProfile Replace the candidate's own profile
	// (PUT /me/profile)
	SaveProfile(ctx context.Context, request SaveProfileRequestObject) (SaveProfileResponseObject, error)
	// GetReadiness Report whether this process can serve traffic
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// ListMembers Everyone in the active workspace
	// (GET /tenant/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// InviteMember Invite an existing account to the workspace
	// (POST /tenant/members)
	InviteMember(ctx context.Context, request InviteMemberRequestObject) (InviteMemberResponseObject, error)
	// RevokeMember Revoke a member's access
	// (DELETE /tenant/members/{membershipId})
	RevokeMember(ctx context.Context, request RevokeMemberRequestObject) (RevokeMemberResponseObject, error)
	// ChangeMemberRole Move a member to another role
	// (PATCH /tenant/members/{membershipId})
	ChangeMemberRole(ctx context.Context, request ChangeMemberRoleRequestObject) (ChangeMemberRoleResponseObject, error)
	// GetTenantQuota The limit, what remains, and where the warning stands
	// (GET /tenant/quota)
	GetTenantQuota(ctx context.Context, request GetTenantQuotaRequestObject) (GetTenantQuotaResponseObject, error)
	// GetTenantUsage What the workspace has used, in the invoice's own terms
	// (GET /tenant/usage)
	GetTenantUsage(ctx context.Context, request GetTenantUsageRequestObject) (GetTenantUsageResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// RequestTokenEmail operation middleware
